//! End-to-end parity tests against MNE-Python ground truth.
//!
//! Verifies coefficient-level and signal-level matching for every
//! DSP operation in the pipeline.
//!
//! Ground truth generated by scripts/full_parity_check.py

use ndarray::Array2;
use std::fs;

fn load_json(name: &str) -> serde_json::Value {
    let path = format!("scripts/parity_vectors/{name}");
    let data = fs::read_to_string(&path).unwrap_or_else(|_| panic!("Missing vector file: {path}"));
    serde_json::from_str(&data).unwrap()
}

fn get_f64_vec(val: &serde_json::Value, key: &str) -> Vec<f64> {
    val[key]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

// ═══════════════════════════════════════════════════════════════════════════
// 1. FILTER DESIGN — full coefficient vectors
// ═══════════════════════════════════════════════════════════════════════════

#[test]
fn parity_highpass_coefficients() {
    let gt = load_json("hp_0p5_256.json");
    let mne_h = get_f64_vec(&gt, "h");
    let rust_h = exg::design_highpass(0.5, 256.0);

    assert_eq!(rust_h.len(), mne_h.len(), "length mismatch");
    let max_diff: f64 = rust_h
        .iter()
        .zip(mne_h.iter())
        .map(|(&r, &m)| (r as f64 - m).abs())
        .fold(0.0_f64, f64::max);
    // f32 output precision: ~1e-7 relative, ~3e-8 absolute for small values
    assert!(max_diff < 5e-8, "HP max coeff diff = {max_diff:.2e}");
}

